//! Replay of the calls `harness/com4_calls.py` recorded from PyBot, against the Rust ports of
//! the 48 bot/compose files of the COM4 workstream. GENERATED by harness/gen_com4_check.py.
//!
//!     RSBOT_TODAY=2026-11-17 ./target/fast/com4_check DIR [--fn NAME|MODULE] [--show N]
//!
//! Functions left out (a parameter or return type the replay cannot build):

#![allow(unused_mut, unused_variables, dead_code)]

extern crate rsbot as crate_;

use crate_::data::Value;
use crate_::state::{Memory, Turn};
use crate_::understood::Understood;
use serde_json::Value as Json;
use std::collections::{BTreeMap, HashMap, HashSet};
use std::io::BufRead;

trait J {
    fn j(&self) -> Json;
}
impl J for bool { fn j(&self) -> Json { Json::Bool(*self) } }
impl J for String { fn j(&self) -> Json { Json::String(self.clone()) } }
impl J for i64 { fn j(&self) -> Json { Json::from(*self) } }
impl J for usize { fn j(&self) -> Json { Json::from(*self as u64) } }
impl J for () { fn j(&self) -> Json { Json::Null } }
// a set is marked, so `same` compares it in any order
impl J for Value {
    fn j(&self) -> Json {
        match self {
            Value::Set(_) => serde_json::json!({"__set__": self.to_plain()}),
            _ => self.to_plain(),
        }
    }
}
impl<T: J> J for Option<T> { fn j(&self) -> Json { match self { Some(v) => v.j(), None => Json::Null } } }
impl<T: J> J for Vec<T> { fn j(&self) -> Json { Json::Array(self.iter().map(J::j).collect()) } }
impl J for HashSet<String> {
    fn j(&self) -> Json {
        let mut v: Vec<&String> = self.iter().collect();
        v.sort();
        Json::Array(v.into_iter().map(|s| Json::String(s.clone())).collect())
    }
}
// a turn as the keys the port keeps, marked so `same` compares only those keys
impl J for &Turn {
    fn j(&self) -> Json {
        serde_json::json!({"__turn__": true, "user": self.user, "bot": self.bot, "module": self.module})
    }
}
impl<A: J, B: J> J for (A, B) { fn j(&self) -> Json { Json::Array(vec![self.0.j(), self.1.j()]) } }

fn sv(v: &Json) -> String { v.as_str().unwrap_or("").to_string() }
fn opt_s(v: &Json) -> Option<String> { v.as_str().map(str::to_string) }
fn strs(v: &Json) -> Vec<String> {
    v.as_array().map(|a| a.iter().map(|x| x.as_str().unwrap_or("").to_string()).collect()).unwrap_or_default()
}
fn opt_strs(v: &Json) -> Option<Vec<String>> { if v.is_null() { None } else { Some(strs(v)) } }
fn truthy(v: &Json) -> bool {
    match v {
        Json::Null => false,
        Json::Bool(b) => *b,
        Json::Number(n) => n.as_f64() != Some(0.0),
        Json::String(s) => !s.is_empty(),
        Json::Array(a) => !a.is_empty(),
        Json::Object(o) => !o.is_empty(),
    }
}
fn mem(v: &Json) -> Memory { v.as_object().map(Memory::from_plain).unwrap_or_default() }
fn und(v: &Json) -> Option<Understood> { serde_json::from_value(v.clone()).ok() }
fn opt_und(v: &Json) -> Option<Option<Understood>> {
    if v.is_null() || v.as_object().is_some_and(|o| o.is_empty()) { Some(None) } else { und(v).map(Some) }
}
fn one_turn(v: &Json) -> Option<Turn> {
    let o = v.as_object()?;
    if o.is_empty() {
        return None;
    }
    turns(&Json::Array(vec![v.clone()])).pop()
}
fn turns(v: &Json) -> Vec<Turn> {
    v.as_array()
        .map(|a| {
            a.iter()
                .map(|t| Turn {
                    user: t["user"].as_str().unwrap_or("").to_string(),
                    bot: t["bot"].as_str().unwrap_or("").to_string(),
                    module: t["module"].as_str().map(str::to_string),
                })
                .collect()
        })
        .unwrap_or_default()
}

fn call(name: &str, a: &[Json]) -> Option<Json> {
    match name {
        "bot.compose:says_it_has_lingered" => { if a.len() != 2 { return None; } let p0 = sv(&a[0]); let p1 = truthy(&a[1]); Some(J::j(&crate_::compose::says_it_has_lingered(&p0, p1))) }
        "bot.compose:negator" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::negator(&p0))) }
        "bot.compose:turned" => { if a.len() != 1 { return None; } let p0 = strs(&a[0]); Some(J::j(&crate_::compose::turned(&p0))) }
        "bot.compose:turns_round" => { if a.len() != 1 { return None; } let p0 = strs(&a[0]); Some(J::j(&crate_::compose::turns_round(&p0))) }
        "bot.compose:negated" => { if a.len() != 3 { return None; } let p0 = sv(&a[0]); let p1 = sv(&a[1]); let p2 = a[2].as_i64().unwrap_or(0); Some(J::j(&crate_::compose::negated(&p0, &p1, p2))) }
        "bot.compose:nearly" => { if a.len() != 3 { return None; } let p0 = sv(&a[0]); let p1 = sv(&a[1]); let p2 = a[2].as_i64().unwrap_or(0); Some(J::j(&crate_::compose::nearly(&p0, &p1, p2))) }
        "bot.compose:doubted" => { if a.len() != 2 { return None; } let p0 = sv(&a[0]); let p1 = a[1].as_i64().unwrap_or(0); Some(J::j(&crate_::compose::doubted(&p0, p1))) }
        "bot.compose:said_again" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::said_again(&p0))) }
        "bot.compose:_opens_with_a_name" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::_opens_with_a_name(&p0))) }
        "bot.compose:greet_with" => { if a.len() != 2 { return None; } let p0 = sv(&a[0]); let p1 = sv(&a[1]); Some(J::j(&crate_::compose::greet_with(&p0, &p1))) }
        "bot.compose:_asks_about_a_thing_nobody_said" => { if a.len() != 3 { return None; } let p0 = sv(&a[0]); let p1 = opt_s(&a[1]); let p2 = sv(&a[2]); Some(J::j(&crate_::compose::_asks_about_a_thing_nobody_said(&p0, p1.as_deref(), &p2))) }
        "bot.compose:pick" => { if a.len() != 3 { return None; } let p0 = strs(&a[0]); let p1 = mem(&a[1]); let p2 = sv(&a[2]); Some(J::j(&crate_::compose::pick(&p0, &p1, &p2))) }
        "bot.compose:_name_just_given" => { if a.len() != 1 { return None; } let p0 = mem(&a[0]); Some(J::j(&crate_::compose::_name_just_given(&p0))) }
        "bot.compose:with_name" => { if a.len() != 2 { return None; } let p0 = opt_s(&a[0]); let p1 = mem(&a[1]); Some(J::j(&crate_::compose::with_name(p0.as_deref(), &p1))) }
        "bot.compose:_says_one_of" => { if a.len() != 2 { return None; } let p0 = sv(&a[0]); let p1 = strs(&a[1]); Some(J::j(&crate_::compose::_says_one_of(&p0, &p1))) }
        "bot.compose:step_when_low" => { if a.len() != 3 { return None; } let p0 = sv(&a[0]); let p1 = mem(&a[1]); let p2 = strs(&a[2]); Some(J::j(&crate_::compose::step_when_low(&p0, &p1, &p2))) }
        "bot.compose.said_about_me:reads_as_somebody_elses_words" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::said_about_me::reads_as_somebody_elses_words(&p0))) }
        "bot.compose.said_about_me:_kind" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::said_about_me::_kind(&p0))) }
        "bot.compose.said_about_me:reads_as_reported_judgement" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::said_about_me::reads_as_reported_judgement(&p0))) }
        "bot.compose.said_about_me:_user_lines" => { if a.len() != 2 { return None; } let p0 = mem(&a[0]); let p1 = a[1].as_i64().unwrap_or(0); Some(J::j(&crate_::compose::said_about_me::_user_lines(&p0, p1))) }
        "bot.compose.said_about_me:_on_the_thread" => { if a.len() != 1 { return None; } let p0 = mem(&a[0]); Some(J::j(&crate_::compose::said_about_me::_on_the_thread(&p0))) }
        "bot.compose.said_about_me:answer_followup" => { if a.len() != 2 { return None; } let p0 = sv(&a[0]); let p1 = mem(&a[1]); Some(J::j(&crate_::compose::said_about_me::answer_followup(&p0, &p1))) }
        "bot.compose.said_about_me:speaks_to_a_self_judgement" => { if a.len() != 1 { return None; } let p0 = sv(&a[0]); Some(J::j(&crate_::compose::said_about_me::speaks_to_a_self_judgement(&p0))) }
        "bot.compose.said_about_me:answer_for" => { if a.len() != 2 { return None; } let p0 = sv(&a[0]); let p1 = mem(&a[1]); Some(J::j(&crate_::compose::said_about_me::answer_for(&p0, &p1))) }
        _ => None,
    }
}

/// Python's result against the port's, allowing for what the two representations cannot share:
/// a set's order, a truthy object read as a bool, and None read as "" for a str contract.
fn same(py: &Json, rs: &Json) -> bool {
    if py == rs {
        return true;
    }
    match (py, rs) {
        (_, Json::Bool(b)) if !py.is_boolean() => truthy(py) == *b,
        (Json::Null, Json::String(s)) => s.is_empty(),
        (Json::Array(x), Json::Object(r)) if r.contains_key("__set__") => {
            let key = |v: &Json| serde_json::to_string(v).unwrap();
            let mut a: Vec<String> = x.iter().map(key).collect();
            let mut b: Vec<String> = r["__set__"].as_array().map(|v| v.iter().map(key).collect()).unwrap_or_default();
            a.sort();
            b.sort();
            a == b
        }
        // Python's `{}` for "no turn"
        (Json::Object(o), Json::Null) => o.is_empty(),
        (Json::Object(o), Json::Object(r)) if r.contains_key("__turn__") => {
            ["user", "bot"].iter().all(|k| o.get(*k).and_then(Json::as_str).unwrap_or("") == r[*k].as_str().unwrap_or(""))
                && o.get("module").cloned().unwrap_or(Json::Null) == r["module"]
        }
        // Python's `()` read as "nothing" where the port's contract is a str
        (Json::Array(x), Json::String(s)) => x.is_empty() && s.is_empty(),
        _ => false,
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let only = args.iter().position(|a| a == "--fn").map(|i| args[i + 1].clone());
    let show: usize = args.iter().position(|a| a == "--show").map(|i| args[i + 1].parse().unwrap()).unwrap_or(3);
    if std::env::var_os("RSBOT_TODAY").is_none() {
        eprintln!("set RSBOT_TODAY=2026-11-17 (the day every recording was made)");
        std::process::exit(2);
    }
    let mut objs: HashMap<String, Json> = HashMap::new();
    for line in std::io::BufReader::new(std::fs::File::open(format!("{dir}/objs.jsonl")).unwrap()).lines() {
        let r: Json = serde_json::from_str(&line.unwrap()).unwrap();
        objs.insert(r["h"].as_str().unwrap().to_string(), r["v"].clone());
    }
    std::panic::set_hook(Box::new(|_| {}));
    let mut tally: BTreeMap<String, [usize; 5]> = BTreeMap::new(); // ok, wrong, unported, panic, skipped
    let mut shown: HashMap<String, usize> = HashMap::new();
    let mut deps: BTreeMap<String, usize> = BTreeMap::new(); // the stub a call stopped at
    for line in std::io::BufReader::new(std::fs::File::open(format!("{dir}/calls.jsonl")).unwrap()).lines() {
        let r: Json = serde_json::from_str(&line.unwrap()).unwrap();
        let name = r["fn"].as_str().unwrap().to_string();
        if only.as_ref().is_some_and(|o| !name.ends_with(&format!(":{o}")) && *o != name && !name.starts_with(&format!("{o}:"))) {
            continue;
        }
        if !r["raised"].is_null() {
            continue;
        }
        let a: Vec<Json> = r["args"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| match x.get("$ref").and_then(Json::as_str) { Some(h) => objs[h].clone(), None => x.clone() })
            .collect();
        let t = tally.entry(name.clone()).or_default();
        let got = std::panic::catch_unwind(|| call(&name, &a));
        match got {
            Ok(None) => t[4] += 1,
            Ok(Some(rs)) => {
                if same(&r["result"], &rs) {
                    t[0] += 1;
                } else {
                    t[1] += 1;
                    let n = shown.entry(name.clone()).or_default();
                    if *n < show {
                        *n += 1;
                        let mut args_s = serde_json::to_string(&r["args"]).unwrap();
                        if args_s.len() > 400 { args_s.truncate(400); }
                        println!("WRONG {name}\n  args {args_s}\n  py   {}\n  rs   {}", r["result"], rs);
                    }
                }
            }
            Err(e) => {
                let msg = e.downcast_ref::<String>().cloned().or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string())).unwrap_or_default();
                if msg.starts_with("UNPORTED") {
                    t[2] += 1;
                    *deps.entry(msg.clone()).or_default() += 1;
                } else {
                    t[3] += 1;
                    let n = shown.entry(name.clone()).or_default();
                    if *n < show {
                        *n += 1;
                        println!("PANIC {name}: {msg}");
                    }
                }
            }
        }
    }
    let mut sum = [0usize; 5];
    for (name, t) in &tally {
        for i in 0..5 { sum[i] += t[i]; }
        if t[1] + t[3] > 0 || only.is_some() {
            println!("{name}: ok {} wrong {} unported {} panic {} skipped {}", t[0], t[1], t[2], t[3], t[4]);
        }
    }
    if args.iter().any(|a| a == "--deps") {
        let mut d: Vec<_> = deps.iter().collect();
        d.sort_by(|a, b| b.1.cmp(a.1));
        for (m, n) in d { println!("{n:6} {m}"); }
    }
    println!("TOTAL: ok {} wrong {} unported {} panic {} skipped {} ({} functions)", sum[0], sum[1], sum[2], sum[3], sum[4], tally.len());
}
